use pstfree::{ltp::{read_node_pc,read_tc,Value,Heap},ndb::Pst};fn main(){let mut p=Pst::open(&std::env::args().nth(1).unwrap()).unwrap();let ns=p.nodes();for n in ns.iter().filter(|n|n.nid_type()==14){let h=Heap::new(p.node_blocks(n.bid_data).unwrap()).unwrap();let info=h.item(h.user_root).unwrap();if [0x218e,0x21ce].contains(&n.nid){println!("COLS {:x} {:?}",n.nid,info[22..].chunks_exact(8).map(|c|format!("{:08x}",u32::from_le_bytes(c[..4].try_into().unwrap()))).collect::<Vec<_>>());}
for r in read_tc(&mut p,n.bid_data,n.bid_sub).unwrap().rows{if let Some(m)=ns.iter().find(|m|m.nid==r.id&&m.nid_type()==4){let pc=read_node_pc(&mut p,m).unwrap();println!("ROW {:x} {:x}",n.nid,m.nid);for (id,v) in r.props {println!("{:04x} equal={} {}",id,pc.props.get(&id).is_some_and(|x|format!("{:?}",x)==format!("{:?}",v)),match v{Value::Int(v)=>format!("int={:x}",v),Value::Bool(v)=>format!("bool={v}"),_=>String::new()});}}}}}
